local ShieldMaker = {}
local PRODUCTS = {
    wooden_shield = { name = "Lesen ščit", woodCost = 2, leatherCost = 1, time = 1, cost = 16, defense = 3, durability = 15, description = "Preprost lesen ščit z usnjato obrobo." },
    iron_bound_shield = { name = "Železno okovan ščit", woodCost = 2, ironCost = 1, leatherCost = 1, time = 3, cost = 60, defense = 6, durability = 25, prestige = 1, description = "Ščit z železnim okovjem." },
    round_shield = { name = "Okrogli ščit", woodCost = 2, ironCost = 1, leatherCost = 1, time = 4, cost = 140, defense = 9, durability = 32, prestige = 3, happiness = 1, description = "Okrogli ščit z bosom." },
    heater_shield = { name = "Trapezni ščit", woodCost = 2, steelCost = 1, leatherCost = 1, time = 6, cost = 320, defense = 13, durability = 42, prestige = 6, happiness = 2, description = "Trapezni ščit s heraldičnim poljem." },
    silver_emblazoned_shield = { name = "Srebrno okrašen ščit", woodCost = 2, steelCost = 1, silverCost = 1, leatherCost = 1, time = 8, cost = 720, defense = 18, durability = 55, prestige = 12, happiness = 3, description = "Srebrno okrašen ščit z grbom." },
    royal_ceremonial_shield = { name = "Kraljevski slovesni ščit", woodCost = 3, steelCost = 2, goldCost = 2, silverCost = 1, jewelCost = 2, pearlCost = 1, leatherCost = 1, time = 13, cost = 2000, defense = 32, durability = 80, prestige = 52, happiness = 11, description = "Veliki kraljevski slovesni ščit z zlatim, draguljnim in bisernim okovjem." },
}
local BUILDINGS = {
    workshop = { name = "Ščitarska delavnica", cost = { gold = 270, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Ščitarska kovačija", cost = { gold = 850, wood = 220, stone = 200, iron = 6 }, upkeep = 20, qualityBonus = 18 },
    painting_room = { name = "Slikalnica", cost = { gold = 1800, wood = 280, stone = 400, silver = 25, paint = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_shield_atelier = { name = "Kraljevski atelje ščitov", cost = { gold = 7000, wood = 500, stone = 700, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 30 },
}
ShieldMaker.woodStock = 14; ShieldMaker.ironStock = 12; ShieldMaker.steelStock = 10; ShieldMaker.leatherStock = 10; ShieldMaker.silverStock = 6; ShieldMaker.goldStock = 6; ShieldMaker.jewelStock = 6; ShieldMaker.pearlStock = 4
ShieldMaker.productStock = {}; ShieldMaker.buildings = {}; ShieldMaker.maker = nil; ShieldMaker.activeMaking = {}; ShieldMaker.totalProducts = 0; ShieldMaker.dayTimer = 0
function ShieldMaker.init() ShieldMaker.woodStock=14; ShieldMaker.ironStock=12; ShieldMaker.steelStock=10; ShieldMaker.leatherStock=10; ShieldMaker.silverStock=6; ShieldMaker.goldStock=6; ShieldMaker.jewelStock=6; ShieldMaker.pearlStock=4; ShieldMaker.productStock={}; ShieldMaker.buildings={}; ShieldMaker.maker=nil; ShieldMaker.activeMaking={}; ShieldMaker.totalProducts=0; ShieldMaker.dayTimer=0; print("[ShieldMaker] Royal Shield Maker System initialized (6 products, 4 buildings)") end
function ShieldMaker.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ShieldMaker.maker={name=n or ("Ščitar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščitar najet: %s (spretnost: %d)",ShieldMaker.maker.name,s),"success") end; return true end
function ShieldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ShieldMaker.build(id) local ok,e=ShieldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ShieldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ShieldMaker.getQualityBonus() local b=0; for _,bd in ipairs(ShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ShieldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ShieldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ShieldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and ShieldMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.leatherCost and ShieldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ShieldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ShieldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ShieldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ShieldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ShieldMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ShieldMaker.maker then return false,"Potreben ščitar" end; return true end
function ShieldMaker.make(pt,qty) qty=qty or 1; local ok,e=ShieldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ShieldMaker.woodStock=ShieldMaker.woodStock-d.woodCost*qty end; if d.ironCost then ShieldMaker.ironStock=ShieldMaker.ironStock-d.ironCost*qty end; if d.steelCost then ShieldMaker.steelStock=ShieldMaker.steelStock-d.steelCost*qty end; if d.leatherCost then ShieldMaker.leatherStock=ShieldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ShieldMaker.silverStock=ShieldMaker.silverStock-d.silverCost*qty end; if d.goldCost then ShieldMaker.goldStock=ShieldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ShieldMaker.jewelStock=ShieldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ShieldMaker.pearlStock=ShieldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ShieldMaker.maker then t=math.max(1,t-math.floor(ShieldMaker.maker.skill/12)) end; table.insert(ShieldMaker.activeMaking,{id="shield_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ShieldMaker.completeMaking(m) local q=1.0+(ShieldMaker.getQualityBonus()/100); if ShieldMaker.maker then q=q+(ShieldMaker.maker.skill/180) end; q=math.min(2.0,q); ShieldMaker.productStock[m.productType]=(ShieldMaker.productStock[m.productType] or 0)+m.quantity; ShieldMaker.totalProducts=ShieldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ShieldMaker.maker then ShieldMaker.maker.itemsMade=ShieldMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ShieldMaker.maker.skill=math.min(100,ShieldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščit izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"shield.completed",{productName=m.productName,defense=m.defense,durability=m.durability}) end end
function ShieldMaker.update(dt) if not _G.state then return end; ShieldMaker.dayTimer=ShieldMaker.dayTimer+dt; if ShieldMaker.dayTimer>=30 then ShieldMaker.dayTimer=0; for i=#ShieldMaker.activeMaking,1,-1 do local m=ShieldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ShieldMaker.completeMaking(m); table.remove(ShieldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ShieldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ShieldMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ShieldMaker.getStats() return {woodStock=ShieldMaker.woodStock,ironStock=ShieldMaker.ironStock,steelStock=ShieldMaker.steelStock,leatherStock=ShieldMaker.leatherStock,silverStock=ShieldMaker.silverStock,goldStock=ShieldMaker.goldStock,jewelStock=ShieldMaker.jewelStock,pearlStock=ShieldMaker.pearlStock,productStock=ShieldMaker.productStock,numBuildings=#ShieldMaker.buildings,hasMaker=ShieldMaker.maker~=nil,makerName=ShieldMaker.maker and ShieldMaker.maker.name or "—",makerSkill=ShieldMaker.maker and ShieldMaker.maker.skill or 0,activeMaking=#ShieldMaker.activeMaking,totalProducts=ShieldMaker.totalProducts} end
return ShieldMaker
